OBJ = "u_brown"
JOINT = "finger_joint"

def check(ctx):
    if ctx.held_object() != OBJ:
        return None
    j = ctx.joint(JOINT)
    if j is None or j["effort"] is None:
        return None
    e = abs(float(j["effort"]))
    if e > ctx.value("max_clamp_effort"):
        return {"value": e, "detail": "finger_joint |effort| " + str(round(e, 3)) + " while holding " + OBJ}
    return None

OBJ = "u_brown"

def check(ctx):
    if ctx.held_object() != OBJ:
        return None
    t = ctx.transform("tcp", OBJ)["translation"]
    if "ref" not in ctx.state:
        ctx.state["ref"] = t
        return None
    d = ctx.dist(t, ctx.state["ref"])
    if d > ctx.value("grasp_slip_tolerance_m"):
        return {"value": d, "detail": OBJ + " moved " + str(round(d, 4)) + " m relative to tcp while held"}
    return None

